INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','noun-modifiers','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"noun-modifiers","title":"Noun modifiers, compound phrases and nominalisation","level":"C1","order":66,"summary":"Build compact noun phrases and understand how turning actions into nouns changes a sentence’s focus.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Nouns can modify other nouns","Measure compounds before nouns","Possessive relationships and of phrases","Nominalisation and clarity"],"rules":[{"title":"Nouns can modify other nouns","explanation":"A noun before another noun often classifies its purpose or type. The final noun is usually the head and controls number and agreement. The first noun often stays singular: a book shelf, two book shelves. Some established compounds keep a plural modifier.","pattern":"a **shoe shop** / two **shoe shops**","commonMistakes":["A sports centre is an established plural modifier. The singular-modifier pattern has lexical exceptions."],"examples":["Choose the modifier: “It is a **2-hour** task to prepare the visitor guide.”","Choose the modifier: “It is a **3-hour** task to restore the old portrait.”"],"skill":"form"},{"title":"Measure compounds before nouns","explanation":"A measurement used as a compound modifier usually has a singular unit and is often hyphenated. When the same measurement follows the noun as a separate phrase, the unit can be plural.","pattern":"a **three-hour** journey / a journey of **three hours**","commonMistakes":["A three-hours journey incorrectly pluralises the unit inside the usual compound modifier."],"examples":["“The task of preparing the visitor guide took 2 **hours**.”","“The task of restoring the old portrait took 3 **hours**.”"],"skill":"meaning"},{"title":"Possessive relationships and of phrases","explanation":"A possessive can express relationships beyond ownership, including time and association. Noun modifiers often classify; possessives often identify a particular relationship. An of phrase may be clearer with long or abstract noun phrases.","pattern":"a **day’s** work / the roof **of the building**","commonMistakes":["A children’s book and a child’s book can differ: the former can name a category, the latter a book belonging to one child."],"examples":["Choose the possessive duration: “We completed a **day’s** work on the visitor guide.”","Choose the possessive duration: “We completed a **day’s** work on the old portrait.”"],"skill":"contrast"},{"title":"Nominalisation and clarity","explanation":"Nominalisation turns an action or quality into a noun, often useful in academic writing: decide → decision, develop → development. It can make a process the subject of a sentence but can also hide who acted. Keep the agent explicit when responsibility matters.","pattern":"We decided quickly. → **Our decision** was quick.","commonMistakes":["Long strings of abstract nouns are not automatically clearer or more precise than verbs."],"examples":["“A decision was made to prepare the visitor guide.” Which revision names the decision-maker clearly? → **The committee decided to prepare the visitor guide.**","“A decision was made to restore the old portrait.” Which revision names the decision-maker clearly? → **The committee decided to restore the old portrait.**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-noun-modifiers"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Build compact noun phrases and understand how turning actions into nouns changes a sentence’s focus.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Nouns can modify other nouns","explanation":"A noun before another noun often classifies its purpose or type. The final noun is usually the head and controls number and agreement. The first noun often stays singular: a book shelf, two book shelves. Some established compounds keep a plural modifier.","pattern":"a **shoe shop** / two **shoe shops**","commonMistakes":["A sports centre is an established plural modifier. The singular-modifier pattern has lexical exceptions."],"examples":["Choose the modifier: “It is a **2-hour** task to prepare the visitor guide.”","Choose the modifier: “It is a **3-hour** task to restore the old portrait.”"],"skill":"form","id":"noun-modifiers-foundation-1","domain":"word-formation","referenceIds":["bc-noun-modifiers"],"readingVersion":"core-2026-09-v3"},{"title":"Measure compounds before nouns","explanation":"A measurement used as a compound modifier usually has a singular unit and is often hyphenated. When the same measurement follows the noun as a separate phrase, the unit can be plural.","pattern":"a **three-hour** journey / a journey of **three hours**","commonMistakes":["A three-hours journey incorrectly pluralises the unit inside the usual compound modifier."],"examples":["“The task of preparing the visitor guide took 2 **hours**.”","“The task of restoring the old portrait took 3 **hours**.”"],"skill":"meaning","id":"noun-modifiers-foundation-2","domain":"word-formation","referenceIds":["bc-noun-modifiers"],"readingVersion":"core-2026-09-v3"},{"title":"Possessive relationships and of phrases","explanation":"A possessive can express relationships beyond ownership, including time and association. Noun modifiers often classify; possessives often identify a particular relationship. An of phrase may be clearer with long or abstract noun phrases.","pattern":"a **day’s** work / the roof **of the building**","commonMistakes":["A children’s book and a child’s book can differ: the former can name a category, the latter a book belonging to one child."],"examples":["Choose the possessive duration: “We completed a **day’s** work on the visitor guide.”","Choose the possessive duration: “We completed a **day’s** work on the old portrait.”"],"skill":"contrast","id":"noun-modifiers-foundation-3","domain":"word-formation","referenceIds":["bc-noun-modifiers"],"readingVersion":"core-2026-09-v3"},{"title":"Nominalisation and clarity","explanation":"Nominalisation turns an action or quality into a noun, often useful in academic writing: decide → decision, develop → development. It can make a process the subject of a sentence but can also hide who acted. Keep the agent explicit when responsibility matters.","pattern":"We decided quickly. → **Our decision** was quick.","commonMistakes":["Long strings of abstract nouns are not automatically clearer or more precise than verbs."],"examples":["“A decision was made to prepare the visitor guide.” Which revision names the decision-maker clearly? → **The committee decided to prepare the visitor guide.**","“A decision was made to restore the old portrait.” Which revision names the decision-maker clearly? → **The committee decided to restore the old portrait.**"],"skill":"application","id":"noun-modifiers-foundation-4","domain":"word-formation","referenceIds":["bc-noun-modifiers"],"readingVersion":"core-2026-09-v3"},{"domain":"coordination","id":"apposition-and-supplements","title":"Apposition, parenthetical additions and supplements","explanation":"Apposition places two expressions referring to the same thing together. An integrated description identifies the referent; a supplementary description adds information about an already identified referent. Commas, dashes or parentheses can mark an added comment. The choice changes how essential the information appears.","pattern":"My sister **Leila** / Leila, **my sister**","examples":["Our guide, **an experienced climber**, led the way.","The writer **Toni Morrison** won the prize."],"commonMistakes":["Do not automatically place commas around every name. The context determines whether the name identifies which person or merely adds information."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"word-formation","id":"inflection-versus-derivation","title":"Inflection versus derivation","explanation":"Inflection supplies grammatical forms of a word, such as books or walked. Derivation creates a related lexical item, sometimes changing its word class: teach → teacher. A word can contain both: teachers includes a derivational ending and a plural ending. Recognising the layers helps you infer meaning and choose a grammatical form.","pattern":"teach + **er** + **s**","examples":["kind → **kindness** creates a noun.","kind → **kinder** creates a comparative form."],"commonMistakes":["A suffix does not have exactly the same effect on every base. Word formation has lexical restrictions, so plausible-looking forms are not automatically established words."],"referenceIds":["cambridge-word-formation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"word-formation","id":"prefixes-and-suffixes","title":"Prefixes, suffixes and word families","explanation":"Prefixes commonly adjust meaning, while suffixes often indicate word class or a related meaning. Learn families such as decide, decision and decisive with their spelling and stress. Negative prefixes include un-, in-/im-/il-/ir-, dis- and non-, but their distribution is not freely interchangeable.","pattern":"**un**happy · care**ful** · care**less**","examples":["possible → **impossible**; legal → **illegal**.","develop → **development**; active → **activity**."],"commonMistakes":["Do not attach the same negative prefix to every adjective. Impossible, unhappy and dishonest are lexical patterns, not choices produced by one universal spelling rule."],"referenceIds":["cambridge-word-formation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"word-formation","id":"conversion-compounding","title":"Conversion, compounds and the head of a compound","explanation":"Conversion uses an existing form as a new word class, such as email as a noun and verb. Compounding combines lexical units into a new expression. English compounds are often headed by the final element, but there are exceptions and idiomatic meanings. Spelling can be open, hyphenated or closed and may change over time.","pattern":"an **email** / to **email** · **toothbrush**","examples":["A **coffee cup** is a kind of cup.","They **bottled** the juice."],"commonMistakes":["A compound’s meaning may not be predictable from its parts. A greenhouse is a particular structure, not simply any house painted green."],"referenceIds":["cambridge-word-formation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"word-formation","id":"clipping-blending-abbreviations","title":"Clipping, blending, acronyms and back-formation","explanation":"Words can arise through shortening, combining portions of words, initials or reanalysis of an apparent ending. These processes explain vocabulary patterns without guaranteeing that every possible new formation is accepted. Acronyms are pronounced as words; initialisms are pronounced letter by letter. Formal writing may need the full expression on first use.","pattern":"advertisement → **ad** · breakfast + lunch → **brunch**","examples":["**UN** is pronounced letter by letter.","**edit** was formed historically from editor."],"commonMistakes":["Word formation is not a substitute for checking an unfamiliar word’s actual use. A recognisable pattern can create a playful one-off expression rather than a standard dictionary item."],"referenceIds":["cambridge-word-formation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"word-formation","id":"nominalisation-and-complements","title":"Nominalisation, agents and dense noun phrases","explanation":"Nominalisation presents an action or quality as a noun. It can help connect ideas across a text, but it can also hide who acts and make sentences dense. Related verbs and nouns take different complement patterns. An of-phrase can be ambiguous between an agent and an affected participant, so use by or a full clause when needed.","pattern":"They investigated it → **their investigation of it**","examples":["**The committee’s rejection of the plan** caused a delay.","**The destruction of the files by the fire** was complete."],"commonMistakes":["Nominalisation is not automatically more formal or better. Compare the clarity of We decided to leave with A decision regarding departure was made."],"referenceIds":["cambridge-word-formation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"word-formation","id":"noun-modifier-number","title":"Nouns as modifiers and compound measurements","explanation":"A noun before another noun commonly classifies it and often has singular form: shoe shop. Some established modifiers are plural, such as sports centre and clothes shop. A measurement compound before a noun normally keeps its unit singular and is often hyphenated. After the noun, the ordinary plural measurement returns.","pattern":"a **five-minute** break / the break lasted **five minutes**","examples":["A **ten-year-old** child needs a ticket.","We visited **a sports centre**."],"commonMistakes":["The common singular-modifier pattern has lexical exceptions. Do not mechanically change every plural noun modifier to singular."],"referenceIds":["cambridge-word-formation","cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["a **shoe shop** / two **shoe shops**","a **three-hour** journey / a journey of **three hours**","a **day’s** work / the roof **of the building**","We decided quickly. → **Our decision** was quick."],"readingVersion":"core-2026-09-v4"},"stage":"6 · Advanced control","prerequisites":["unreal-subjunctive"],"readingReferenceIds":["bc-noun-modifiers","cambridge-comprehensive-scope","cambridge-word-formation"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='noun-modifiers'
